    {
      "keystrokes": "cat > cli.js << 'ENDOFFILE'
#!/usr/bin/env node
/**
 * Clawd CLI Configuration - Ocean Blue Variant
 * 
 * Custom Clawd mascot variant for Claude Code CLI
 * Features: Top hat, both arms, ocean blue color scheme
 * 
 * @version 1.0.0
 * @author Custom Clawd Modifier
 */

'use strict';

/**
 * Ocean Blue Color Configuration
 * Uses both RGB (true-color) and ANSI (8/16-color) formats
 */
const clawdColors = {
  // True-color terminals (24-bit RGB)
  rgb: {
    body: 'rgb(100,149,237)',    // Ocean blue
    background: 'rgb(0,0,0)',    // Black
    hat: 'rgb(0,0,0)',           // Black top hat
    band: 'rgb(100,149,237)'     // Blue hat band
  },
  // ANSI fallback (8/16-color terminals)
  ansi: {
    body: 'ansi:blueBright',
    background: 'ansi:black',
    hat: 'ansi:black',
    band: 'ansi:blueBright'
  }
};

/**
 * Small Clawd - Prompt Icon
 * Features: Top hat and both arms
 * 
 * ASCII Art:
 *    ┌─┐        (top hat with band)
 * ╱▐▛███▜▌╲     (head with left arm ╱ and right arm ╲)
 * ▝▜█████▛▘     (body)
 *   ▘▘ ▝▝       (feet)
 */
const smallClawd = {
  name: 'Clawd Ocean Blue - Prompt Icon',
  description: 'Small Clawd with top hat and both arms for CLI prompt',
  art: [
    '   ┌─┐',
    '╱▐▛███▜▌╲',
    '▝▜█████▛▘',
    '  ▘▘ ▝▝'
  ],
  dimensions: {
    width: 11,
    height: 4
  },
  theme: clawdColors
};

/**
 * Large Clawd - Loading Screen Mascot
 * Features: Top hat variant for welcome/loading screen
 * 
 * ASCII Art:
 *     ┌─────┐     (top hat brim and crown)
 *    ████████     (hat base)
 *   █████████     (head)
 *  ██▄█████▄██    (ears with ▄ lower half blocks)
 *   █████████     (body)
 *  █ █   █ █      (eyes/feet pattern)
 */
const largeClawd = {
  name: 'Clawd Ocean Blue - Loading Screen',
  description: 'Large Clawd with top hat for loading/welcome screen',
  art: [
    '     ┌─────┐',
    '    ████████',
    '   █████████',
    '  ██▄█████▄██',
    '   █████████',
    '  █ █   █ █'
  ],
  dimensions: {
    width: 13,
    height: 6
  },
  theme: clawdColors
};

/**
 * Theme Configuration for Ink Rendering
 * Compatible with Ink's $ styled component system
 */
const clawdThemes = {
  dark: {
    clawd_body: clawdColors.rgb.body,
    clawd_background: clawdColors.rgb.background,
    clawd_hat: clawdColors.rgb.hat,
    clawd_band: clawdColors.rgb.band
  },
  light: {
    clawd_body: clawdColors.rgb.body,
    clawd_background: 'rgb(255,255,255)',
    clawd_hat: 'rgb(50,50,50)',
    clawd_band: clawdColors.rgb.body
  },
  ansi: {
    clawd_body: clawdColors.ansi.body,
    clawd_background: clawdColors.ansi.background,
    clawd_hat: clawdColors.ansi.hat,
    clawd_band: clawdColors.ansi.band
  }
};

/**
 * Render small Clawd prompt icon
 * @param {Object} options - Rendering options
 * @returns {string} Formatted ASCII art
 */
function renderSmallClawd(options = {}) {
  const { colorize = false } = options;

  if (colorize) {
    // Colorized version for display
    return smallClawd.art.map(line => 
      `\x1b[38;2;100;149;237m${line}\x1b[0m`
    ).join('\n');
  }

  return smallClawd.art.join('\n');
}

/**
 * Render large Clawd loading screen mascot
 * @param {Object} options - Rendering options
 * @returns {string} Formatted ASCII art
 */
function renderLargeClawd(options = {}) {
  const { colorize = false } = options;

  if (colorize) {
    // Colorized version for display
    return largeClawd.art.map(line => 
      `\x1b[38;2;100;149;237m${line}\x1b[0m`
    ).join('\n');
  }

  return largeClawd.art.join('\n');
}

/**
 * Export configuration for use in Claude Code CLI
 */
module.exports = {
  colors: clawdColors,
  themes: clawdThemes,
  smallClawd,
  largeClawd,
  renderSmallClawd,
  renderLargeClawd
};

/**
 * Demo/Test mode - run directly to preview
 */
if (require.main === module) {
  console.log('='.repeat(40));
  console.log('  Clawd Ocean Blue Variant Preview');
  console.log('='.repeat(40));
  console.log('');
  console.log('Small Clawd (Prompt Icon):');
  console.log(renderSmallClawd());
  console.log('');
  console.log('Large Clawd (Loading Screen):');
  console.log(renderLargeClawd());
  console.log('');
  console.log('Color Configuration:');
  console.log(`  RGB Body: ${clawdColors.rgb.body}`);
  console.log(`  ANSI Body: ${clawdColors.ansi.body}`);
  console.log('='.repeat(40));
}
ENDOFFILE\n",
